precision mediump float; in vec2 v_uv; uniform sampler2D u_a; uniform sampler2D u_b; out vec4 o;
void main() {
  vec2 uv = vec2(fract(v_uv.x * 2.0), v_uv.y);
  o = v_uv.x < 0.5 ? texture(u_a, uv) : texture(u_b, uv);
}
